//! R7 live Rust normalized books gate. Public market data only; no trading.
use futures_util::{SinkExt,StreamExt};use serde_json::json;use spotarb_native_market_core::{owner_index,HistorySink,CoreError,Owner,RawFrame,Update,Venue};use std::{collections::HashSet,time::{Duration,Instant,SystemTime,UNIX_EPOCH}};use tokio_tungstenite::{connect_async,tungstenite::Message};
struct H{n:u64}impl HistorySink for H{fn accept(&mut self,_:&RawFrame,_:&Update)->Result<(),CoreError>{self.n+=1;Ok(())}}
fn wall()->i64{SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_millis() as i64}
#[tokio::main]async fn main(){let bases=std::env::var("R7_BASES").unwrap_or("BTC,ETH,SOL".into()).split(',').map(|s|s.to_string()).collect::<Vec<_>>();let secs=std::env::var("R7_SECONDS").ok().and_then(|s|s.parse().ok()).unwrap_or(20);let start=Instant::now();let mut owners=(0..12).map(|i|Owner::new(i,12,800).unwrap()).collect::<Vec<_>>();let mut h=H{n:0};let mut seen_b=HashSet::new();let mut seen_o=HashSet::new();let mut errors=0u64;
let streams=bases.iter().map(|b|format!("{}usdt@bookTicker",b.to_lowercase())).collect::<Vec<_>>().join("/");let(mut b,_)=connect_async(format!("wss://fstream.binance.com/stream?streams={streams}")).await.unwrap();let(mut o,_)=connect_async("wss://ws.okx.com:8443/ws/v5/public").await.unwrap();let args=bases.iter().map(|x|json!({"channel":"books5","instId":format!("{x}-USDT")})).collect::<Vec<_>>();o.send(Message::Text(json!({"op":"subscribe","args":args}).to_string())).await.unwrap();
while start.elapsed()<Duration::from_secs(secs){tokio::select!{
 x=b.next()=>if let Some(Ok(Message::Text(raw)))=x{let w=wall();let f=RawFrame{source:None,venue:Venue::BinanceFutures,epoch:1,received_ns:start.elapsed().as_nanos() as u64,received_wall_ms:w,raw};match spotarb_native_market_core::parse(&f){Ok(u)=>{seen_b.insert(u.base.clone());let i=owner_index(&u.base,12);if owners[i].ingest_parsed(&f,u,&mut h).is_err(){errors+=1}},Err(_)=>errors+=1}},
 x=o.next()=>if let Some(Ok(Message::Text(raw)))=x{if raw.contains("\"event\""){continue}let w=wall();let f=RawFrame{source:None,venue:Venue::OkxSpot,epoch:1,received_ns:start.elapsed().as_nanos() as u64,received_wall_ms:w,raw};match spotarb_native_market_core::parse(&f){Ok(u)=>{seen_o.insert(u.base.clone());let i=owner_index(&u.base,12);if owners[i].ingest_parsed(&f,u,&mut h).is_err(){errors+=1}},Err(_)=>errors+=1}}
}}
let mut paired=0;let mut normalized=0;for base in &bases{let i=owner_index(base,12);let(s,f)=owners[i].snapshot_pair(base);if s.is_some(){normalized+=1}if f.is_some(){normalized+=1}if s.is_some()&&f.is_some(){paired+=1}}
let missing_b=bases.iter().filter(|x|!seen_b.contains(*x)).cloned().collect::<Vec<_>>();let missing_o=bases.iter().filter(|x|!seen_o.contains(*x)).cloned().collect::<Vec<_>>();println!("{}",json!({"r7_live_books":errors==0&&paired==bases.len(),"requested":bases.len(),"binance_seen":seen_b.len(),"okx_seen":seen_o.len(),"missing_binance":missing_b,"missing_okx":missing_o,"normalized_sides":normalized,"paired_books":paired,"history_accepted":h.n,"errors":errors,"trading":false}));}